        pullSoundRef,
        chickenCluckRef,
        wingFlapRef,
        victoryFanfareRef,
        tensionSoundRef,
        ropeCreakRef
      }).forEach(ref => {
        if (ref.current) {
          ref.current.pause()
          ref.current.src = ''
        }
      })
    }
