const DramaticSoundEffects = ({ ropePosition, isGameActive, winner }) => {
  const audioContextRef = useRef()
  const lastIntensityRef = useRef(0)
  const tensionTimeoutRef = useRef()
  const prevWinnerRef = useRef(null)
  const currentDramaticSoundRef = useRef(null)
  const isPlayingDramaticRef = useRef(false)

const playDramaticRiser = (intensity = 0.5) => {
  if (!audioContextRef.current || !isGameActive) return

  // Stop any existing dramatic sound
  if (currentDramaticSoundRef.current) {
    try {
      currentDramaticSoundRef.current.stop()
    } catch (e) {
      // Sound may have already stopped
    }
  }

  const ctx = audioContextRef.current
  const gainNode = ctx.createGain()
  gainNode.connect(ctx.destination)

  // Create a dramatic rising sound
  const oscillator = ctx.createOscillator()
  const filter = ctx.createBiquadFilter()

  oscillator.connect(filter)
  filter.connect(gainNode)

  const startFreq = 80 + intensity * 40
  const endFreq = 200 + intensity * 100
  const duration = 2.5

  oscillator.frequency.setValueAtTime(startFreq, ctx.currentTime)
  oscillator.frequency.exponentialRampToValueAtTime(endFreq, ctx.currentTime + duration)
  oscillator.type = 'sawtooth'

  filter.frequency.setValueAtTime(1000, ctx.currentTime)
  filter.frequency.exponentialRampToValueAtTime(3000, ctx.currentTime + duration)
  filter.Q.setValueAtTime(5, ctx.currentTime)

  gainNode.gain.setValueAtTime(0.02, ctx.currentTime)
  gainNode.gain.linearRampToValueAtTime(intensity * 0.08, ctx.currentTime + 1)
  gainNode.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration)

  oscillator.start()
  oscillator.stop(ctx.currentTime + duration)

  // Track the current sound for cleanup
  currentDramaticSoundRef.current = oscillator
  isPlayingDramaticRef.current = true

  // Clear the reference when sound ends
  setTimeout(() => {
    currentDramaticSoundRef.current = null
    isPlayingDramaticRef.current = false
  }, duration * 1000)
}

const stopDramaticSounds = () => {
  if (currentDramaticSoundRef.current) {
    try {
      currentDramaticSoundRef.current.stop()
    } catch (e) {
      // Sound may have already stopped
    }
    currentDramaticSoundRef.current = null
  }
  isPlayingDramaticRef.current = false

  if (tensionTimeoutRef.current) {
    clearTimeout(tensionTimeoutRef.current)
    tensionTimeoutRef.current = null
  }
}

// Monitor rope position for dramatic effects
useEffect(() => {
  const intensity = Math.abs(ropePosition) / 10
  const intensityChange = intensity - lastIntensityRef.current

  // Stop dramatic sounds if game is not active
  if (!isGameActive) {
    stopDramaticSounds()
    return
  }

  // Clear previous timeout
  if (tensionTimeoutRef.current) {
    clearTimeout(tensionTimeoutRef.current)
    tensionTimeoutRef.current = null
  }

  // High tension zone (above 70% rope position)
  if (intensity > 0.7) {
    // Start dramatic riser if intensity increased significantly or if not already playing
    if ((intensityChange > 0.15 && intensityChange > 0) || (!isPlayingDramaticRef.current && intensity > 0.8)) {
      playDramaticRiser(intensity)
    }

    // Close call sound for near wins (above 90%)
    if (intensity > 0.9) {
      tensionTimeoutRef.current = setTimeout(() => {
        if (isGameActive && Math.abs(ropePosition) / 10 > 0.9) {
          playCloseCallSound()
        }
      }, 500)
    }
  } else {
    // Low tension - stop dramatic sounds when rope position becomes neutral
    if (intensity < 0.5 && isPlayingDramaticRef.current) {
      stopDramaticSounds()
    }
  }

  lastIntensityRef.current = intensity
}, [ropePosition, isGameActive])

// Stop sounds when game ends
useEffect(() => {
  if (!isGameActive) {
    stopDramaticSounds()
  }
}, [isGameActive])

// Cleanup when component unmounts
useEffect(() => {
  return () => {
    stopDramaticSounds()
  }
}, [])

// Play victory/defeat sounds
useEffect(() => {
  if (winner && winner !== prevWinnerRef.current) {
    // Stop any ongoing dramatic sounds immediately when someone wins
    stopDramaticSounds()

    const isRed = winner.includes('Red')
    playVictoryFanfare(isRed)

    // Play defeat sound after a delay for losing team
    setTimeout(() => {
      playDefeatSound()
    }, 1000)
  }
  prevWinnerRef.current = winner
}, [winner])

// Reset state when game resets
useEffect(() => {
  if (isGameActive && prevWinnerRef.current && !winner) {
    // Game was reset - clear previous winner and stop sounds
    stopDramaticSounds()
    lastIntensityRef.current = 0
    prevWinnerRef.current = null
  }
}, [isGameActive, winner])

