const DramaticSoundEffects = ({ ropePosition, isGameActive, winner }) => {
  const audioContextRef = useRef()
  const lastIntensityRef = useRef(0)
  const tensionTimeoutRef = useRef()
  const prevWinnerRef = useRef(null)
  const currentDramaticSoundRef = useRef(null)
  const isPlayingDramaticRef = useRef(false)
  const lastDramaticTriggerTime = useRef(0)
  const lastCloseCallTime = useRef(0)
  const intensityHistoryRef = useRef([])
  const stableIntensityRef = useRef(0)

// Monitor rope position for dramatic effects
useEffect(() => {
  const currentTime = Date.now()
  const intensity = Math.abs(ropePosition) / 10

  // Add current intensity to history and keep only last 10 readings for stability
  intensityHistoryRef.current.push(intensity)
  if (intensityHistoryRef.current.length > 10) {
    intensityHistoryRef.current.shift()
  }

  // Calculate stable intensity (average of recent readings to smooth out rapid changes)
  const stableIntensity = intensityHistoryRef.current.reduce((sum, val) => sum + val, 0) / intensityHistoryRef.current.length
  stableIntensityRef.current = stableIntensity

  // Stop dramatic sounds if game is not active
  if (!isGameActive) {
    stopDramaticSounds()
    return
  }

  // Clear previous close call timeout
  if (tensionTimeoutRef.current) {
    clearTimeout(tensionTimeoutRef.current)
    tensionTimeoutRef.current = null
  }

  // DRAMATIC RISER LOGIC - Only trigger if:
  // 1. Stable intensity is high (>75%)
  // 2. There's been a sustained increase over time
  // 3. We haven't played a dramatic sound recently (throttle)
  // 4. We're not already playing one
  const dramaticCooldown = 4000 // 4 seconds between dramatic sounds
  const intensityThreshold = 0.75
  const sustainedIncreaseThreshold = 0.25

  if (stableIntensity > intensityThreshold && 
      !isPlayingDramaticRef.current && 
      currentTime - lastDramaticTriggerTime.current > dramaticCooldown) {

    // Check if there's been a sustained increase by comparing with older readings
    const olderIntensityAverage = intensityHistoryRef.current.length >= 5 
      ? intensityHistoryRef.current.slice(0, 5).reduce((sum, val) => sum + val, 0) / 5 
      : 0

    const sustainedIncrease = stableIntensity - olderIntensityAverage

    if (sustainedIncrease > sustainedIncreaseThreshold) {
      playDramaticRiser(stableIntensity)
      lastDramaticTriggerTime.current = currentTime
    }
  }

  // CLOSE CALL LOGIC - Only for very high stable intensity
  // Throttle close call sounds to prevent spam
  const closeCallCooldown = 2000 // 2 seconds between close calls

  if (stableIntensity > 0.9 && currentTime - lastCloseCallTime.current > closeCallCooldown) {
    tensionTimeoutRef.current = setTimeout(() => {
      if (isGameActive && stableIntensityRef.current > 0.9) {
        playCloseCallSound()
        lastCloseCallTime.current = Date.now()
      }
    }, 800) // Longer delay to ensure it's truly sustained
  }

  // TENSION RELIEF - Stop dramatic sounds when intensity drops significantly
  // Use stable intensity to avoid stopping due to momentary fluctuations
  if (stableIntensity < 0.4 && isPlayingDramaticRef.current) {
    stopDramaticSounds()
  }

  lastIntensityRef.current = intensity
}, [ropePosition, isGameActive])

// Stop sounds when game ends
useEffect(() => {
  if (!isGameActive) {
    stopDramaticSounds()
    // Clear intensity history when game stops
    intensityHistoryRef.current = []
    stableIntensityRef.current = 0
  }
}, [isGameActive])

// Cleanup when component unmounts
useEffect(() => {
  return () => {
    stopDramaticSounds()
    intensityHistoryRef.current = []
  }
}, [])

// Reset state when game resets
useEffect(() => {
  if (isGameActive && prevWinnerRef.current && !winner) {
    // Game was reset - clear all state and timers
    stopDramaticSounds()
    lastIntensityRef.current = 0
    lastDramaticTriggerTime.current = 0
    lastCloseCallTime.current = 0
    intensityHistoryRef.current = []
    stableIntensityRef.current = 0
    prevWinnerRef.current = null
  }
}, [isGameActive, winner])

